sys_script.script:
(function executeRule(current, previous) {
    try {

        // Get complaint text from short description and/or description
        var shortDesc = current.getValue('short_description') || '';
        var description = current.getValue('description') || '';

        var complaintText = shortDesc + ' ' + description;
        complaintText = complaintText.trim();

        if (!complaintText) {
            return;
        }

        // =========================================================
        // 1. NLP ENGINE
        // Handles:
        // - Complaint Type
        // - AI Urgency Score
        // - AI Urgency Level
        // - AI Urgency Reason
        // =========================================================

        var nlpEngine = new x_2145749_qc.ComplaintNLPEngine();
        var nlpResult = nlpEngine.analyze(complaintText);

        // Prevent recursive Business Rule execution
        current.setWorkflow(false);

        // ---------------------------------------------------------
        // Complaint Type
        // ---------------------------------------------------------

        var currentType = current.getValue(
            'x_2145749_qc_complaint_type'
        );

        if (!currentType &&
            nlpResult.category &&
            nlpResult.category !== 'other') {

            current.setValue(
                'x_2145749_qc_complaint_type',
                nlpResult.category
            );
        }

        // ---------------------------------------------------------
        // AI Urgency fields
        // ---------------------------------------------------------

        current.setValue(
            'x_2145749_qc_ai_urgency_score',
            nlpResult.score
        );

        current.setValue(
            'x_2145749_qc_ai_urgency_level',
            nlpResult.level
        );

        current.setValue(
            'x_2145749_qc_ai_urgency_reason',
            nlpResult.reason
        );


        // =========================================================
        // 2. SENTIMENT
        // Use ComplaintTriageEngine ONLY for sentiment.
        // We do NOT use its urgency result.
        // =========================================================

        var sentimentEngine =
            new x_2145749_qc.ComplaintTriageEngine();

        var sentimentResult =
            sentimentEngine.triage(complaintText, 0);

        current.setValue(
            'x_2145749_qc_ai_sentiment',
            sentimentResult.sentiment
        );


        // =========================================================
        // Save the case
        // =========================================================

        current.update();

        gs.debug(
            'AI Analyze Complaint: Processed case ' +
            current.getUniqueValue() +
            ' - Category: ' +
            nlpResult.category +
            ', Score: ' +
            nlpResult.score +
            ', Level: ' +
            nlpResult.level +
            ', Sentiment: ' +
            sentimentResult.sentiment
        );

    } catch (e) {

        gs.error(
            'AI Analyze Complaint: Error processing case ' +
            current.getUniqueValue() +
            ' - ' +
            e.message
        );
    }

})(current, previous);
